INSERT INTO vulnerabilities (id, cve_id, title, description, severity, cvss_score, exploit_available, published_at, discovered_at, package_id, affected_versions, fix_available, fixed_in_version) VALUES
  ('u0000000-0000-0000-0000-000000000001', 'CVE-2024-45801', 'Prototype Pollution in lodash', 'lodash is vulnerable to prototype pollution via the merge, mergeWith, and defaultsDeep functions. An attacker can modify the prototype of base objects, potentially leading to arbitrary code execution.', 'critical', 9.8, true, now() - interval '94 days', now() - interval '141 days', 'p0000000-0000-0000-0000-000000000001', '*', true, '4.17.21'),
  ('u0000000-0000-0000-0000-000000000002', 'CVE-2024-45802', 'SSRF in axios', 'axios is vulnerable to Server-Side Request Forgery (SSRF) when processing absolute URLs on relative request options.', 'high', 7.5, true, now() - interval '367 days', now() - interval '37 days', 'p0000000-0000-0000-0000-000000000003', '*', true, '1.7.7'),
  ('u0000000-0000-0000-0000-000000000003', 'CVE-2024-45803', 'XSS in react-dom', 'react-dom contains a cross-site scripting vulnerability in the createRoot API when rendering untrusted input.', 'medium', 5.4, false, now() - interval '311 days', now() - interval '126 days', 'p0000000-0000-0000-0000-000000000005', '*', true, '18.3.1'),
  ('u0000000-0000-0000-0000-000000000004', 'CVE-2024-45804', 'Algorithm confusion in jsonwebtoken', 'jsonwebtoken is vulnerable to algorithm confusion when the secret key is public. An attacker can forge tokens with HS256 using the public RSA key.', 'critical', 9.1, true, now() - interval '165 days', now() - interval '47 days', 'p0000000-0000-0000-0000-000000000007', '*', true, '9.0.2'),
  ('u0000000-0000-0000-0000-000000000005', 'CVE-2024-45805', 'ReDoS in bcrypt', 'bcrypt is vulnerable to regular expression denial of service when processing specially crafted passwords.', 'medium', 5.3, false, now() - interval '340 days', now() - interval '140 days', 'p0000000-0000-0000-0000-000000000010', '*', true, '5.1.1'),
  ('u0000000-0000-0000-0000-000000000006', 'CVE-2024-45806', 'Prototype Pollution in minimist', 'minimist is vulnerable to prototype pollution via the key argument when parsing command-line options.', 'high', 7.5, true, now() - interval '138 days', now() - interval '113 days', 'p0000000-0000-0000-0000-000000000013', '*', true, '1.2.8'),
  ('u0000000-0000-0000-0000-000000000007', 'CVE-2024-45807', 'ReDoS in handlebars', 'handlebars is vulnerable to regular expression denial of service via specially crafted templates.', 'medium', 5.3, false, now() - interval '383 days', now() - interval '143 days', 'p0000000-0000-0000-0000-000000000016', '*', true, '4.7.8'),
  ('u0000000-0000-0000-0000-000000000008', 'CVE-2024-45808', 'Path traversal in request', 'request library is vulnerable to path traversal when following redirects to file URLs.', 'high', 7.5, false, now() - interval '395 days', now() - interval '56 days', 'p0000000-0000-0000-0000-000000000017', '*', false, null),
  ('u0000000-0000-0000-0000-000000000009', 'CVE-2024-45809', 'ReDoS in moment', 'moment is vulnerable to regular expression denial of service in the parse function.', 'low', 3.7, false, now() - interval '234 days', now() - interval '84 days', 'p0000000-0000-0000-0000-000000000022', '*', true, '2.30.1'),
  ('u0000000-0000-0000-0000-000000000010', 'CVE-2024-45810', 'SSRF in pg', 'node-postgres is vulnerable to code execution via the connection string when using Unix domain sockets.', 'high', 8.1, true, now() - interval '362 days', now() - interval '176 days', 'p0000000-0000-0000-0000-000000000027', '*', true, '8.13.0'),
